package com.celik.kingdoms;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.*;
import com.mojang.brigadier.context.CommandContext;
import net.minecraft.commands.*;
import net.minecraft.commands.arguments.EntityArgument;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.permissions.Permissions;
import java.util.*;
import java.lang.reflect.Field;
import static net.minecraft.commands.Commands.*;
import static com.celik.kingdoms.Rules.*;

public final class KingdomCommands {
    private static final Set<String> MONEY_SETTINGS=Set.of("creationFee","expansionFee","outpostFee","upkeepPerMember","upkeepBase","protectionFee");
    private static KingdomService s(){if(KingdomsMod.service==null)throw new IllegalArgumentException("Kingdoms is not ready.");return KingdomsMod.service;}
    private static int player(CommandContext<CommandSourceStack> c,java.util.function.Consumer<ServerPlayer> work){try{ServerPlayer p=c.getSource().getPlayerOrException();Ui.run(p,()->work.accept(p));return 1;}catch(Exception e){c.getSource().sendFailure(net.minecraft.network.chat.Component.literal(Ui.caps(e.getMessage())));return 0;}}
    private static String str(CommandContext<CommandSourceStack> c,String name){return StringArgumentType.getString(c,name);}
    private static UUID target(String text){try{return UUID.fromString(text);}catch(IllegalArgumentException e){var p=s().server.getPlayerList().getPlayerByName(text);if(p!=null)return p.getUUID();for(Kingdom k:s().state.kingdoms.values())for(var entry:k.members.entrySet())if(entry.getValue().equalsIgnoreCase(text))return entry.getKey();throw new IllegalArgumentException("Unknown name. Use an online name, known member, or UUID.");}}
    private static <T extends Enum<T>> T option(Class<T> type,String value){try{return Enum.valueOf(type,value.toUpperCase(Locale.ROOT));}catch(Exception e){throw new IllegalArgumentException("Choose: "+Arrays.toString(type.getEnumConstants()));}}
    public static void register(CommandDispatcher<CommandSourceStack> d){
        var root=literal("kingdom").executes(c->player(c,Ui::home));
        d.register(literal("artifact").executes(c->player(c,p->s().artifacts.menu(p))));
        root.then(literal("artifacts").executes(c->player(c,p->s().artifacts.menu(p))));
        d.register(literal("airdrop").executes(c->player(c,p->AirDropUi.list(p,0))));
        root.then(literal("airdrops").executes(c->player(c,p->AirDropUi.list(p,0))));
        root.then(literal("help").executes(c->player(c,Ui::help)));
        root.then(literal("create").then(argument("name",StringArgumentType.greedyString()).executes(c->player(c,p->Ui.confirm(p,"Create kingdom",List.of(str(c,"name"),"Creation fee: "+s().money(s().config.creationFee),"Your current chunk will be claimed.","Must be more than "+s().config.kingdomCreationBufferChunks+" chunks from another kingdom.","Must be outside the "+s().config.spawnClaimProtectionChunks+" chunk spawn radius.","Starter war protection: "+Ui.time(s().config.minute(s().config.newKingdomProtectionMinutes))),()->s().create(p,str(c,"name")))))));
        root.then(literal("icon").executes(c->player(c,p->{s().setIcon(p);Ui.tell(p,"Kingdom icon updated from your held item.",false);})));
        root.then(literal("leaderboard").executes(c->player(c,Ui::leaderboard)));
        var alliance=literal("alliance").executes(c->player(c,DiplomacyUi::alliances));
        alliance.then(literal("request").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->s().diplomacy.request(p,s().named(str(c,"kingdom")).id)))));
        alliance.then(literal("accept").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->{Kingdom k=s().named(str(c,"kingdom"));Ui.confirm(p,"Accept alliance",List.of(k.display(),"War participation still requires approval."),()->s().diplomacy.respond(p,k.id,true));}))));
        alliance.then(literal("decline").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->s().diplomacy.respond(p,s().named(str(c,"kingdom")).id,false)))));
        alliance.then(literal("cancel").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->s().diplomacy.cancel(p,s().named(str(c,"kingdom")).id)))));
        alliance.then(literal("remove").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->{Kingdom k=s().named(str(c,"kingdom"));Ui.confirm(p,"End alliance",List.of(k.display()),()->s().diplomacy.remove(p,k.id));}))));root.then(alliance);
        root.then(literal("warinvite").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->s().diplomacy.inviteWar(p,s().named(str(c,"kingdom")).id)))));
        root.then(literal("warjoin").executes(c->player(c,p->DiplomacyUi.warInvites(p,0))));
        root.then(literal("beacon").executes(c->player(c,Ui::beacon)));root.then(literal("core").executes(c->player(c,Ui::core)));
        root.then(literal("claim").executes(c->player(c,p->{s().claim(p);Ui.claims(p);})));
        root.then(literal("outpost").executes(c->player(c,p->Ui.confirm(p,"Claim outpost",List.of("Cost: "+s().money(s().config.outpostFee),"Uses "+s().config.outpostClaimWeight+" claim slots.","Does not need to connect to existing land."),()->s().outpost(p)))));
        root.then(literal("unclaim").executes(c->player(c,p->Ui.confirm(p,"Unclaim current chunk",List.of("Land becomes unprotected. No refund."),()->s().unclaim(p)))));
        root.then(literal("disband").executes(c->player(c,p->Ui.confirm(p,"Disband kingdom",List.of("All claims are released. Treasury is forfeited."),()->s().disband(p)))));
        root.then(literal("invite").then(argument("player",EntityArgument.player()).executes(c->player(c,p->{try{ServerPlayer other=EntityArgument.getPlayer(c,"player");s().invite(p,other.getUUID());Ui.tell(other,p.getName().getString()+" invited you to a kingdom. Use /kingdom join.",false);Ui.tell(p,"Invitation sent.",false);}catch(com.mojang.brigadier.exceptions.CommandSyntaxException e){throw new IllegalArgumentException(e.getMessage());}}))));
        root.then(literal("join").executes(c->player(c,p->{s().join(p);Ui.home(p);})));
        root.then(literal("leave").executes(c->player(c,p->Ui.confirm(p,"Leave kingdom",List.of("Your member permissions will be removed."),()->s().removeMember(p,p.getUUID())))));
        root.then(literal("kick").then(argument("player",StringArgumentType.word()).executes(c->player(c,p->Ui.confirm(p,"Remove member",List.of(str(c,"player")),()->s().removeMember(p,target(str(c,"player"))))))));
        for(boolean withdraw:new boolean[]{false,true})root.then(literal(withdraw?"withdraw":"deposit").then(argument("amount",StringArgumentType.greedyString()).executes(c->player(c,p->{long amount=MoneyInput.parsePositive(str(c,"amount"));if(withdraw)Ui.confirm(p,"Withdraw",List.of(s().money(amount)),()->s().treasury(p,amount,true));else{s().treasury(p,amount,false);Ui.treasury(p);}}))));
        root.then(literal("mayor").then(argument("player",StringArgumentType.word()).then(argument("enabled",BoolArgumentType.bool()).executes(c->player(c,p->Ui.confirm(p,"Change mayor",List.of(str(c,"player"),"Mayors have full management access."),()->s().setMayor(p,target(str(c,"player")),BoolArgumentType.getBool(c,"enabled"))))))));
        root.then(literal("grant").then(argument("player",StringArgumentType.word()).then(argument("permission",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Arrays.stream(Permission.values()).map(x->x.name().toLowerCase(Locale.ROOT)),b)).then(argument("enabled",BoolArgumentType.bool()).executes(c->player(c,p->{s().grant(p,target(str(c,"player")),option(Permission.class,str(c,"permission")),BoolArgumentType.getBool(c,"enabled"));Ui.tell(p,"Permission updated.",false);}))))));
        root.then(literal("flag").then(argument("flag",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Arrays.stream(Flag.values()).map(x->x.name().toLowerCase(Locale.ROOT)),b)).then(argument("enabled",BoolArgumentType.bool()).executes(c->player(c,p->{s().setFlag(p,option(Flag.class,str(c,"flag")),BoolArgumentType.getBool(c,"enabled"));Ui.settings(p);})))));
        root.then(literal("war").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->player(c,p->{Kingdom k=s().named(str(c,"kingdom"));DiplomacyUi.declare(p,k.id);}))));
        root.then(literal("protect").executes(c->player(c,p->Ui.confirm(p,"Buy protection",List.of("Cost: "+s().money(s().config.protectionFee)),()->s().protect(p)))));
        root.then(literal("acknowledge").executes(c->player(c,p->{s().acknowledge(p);Ui.home(p);})));root.then(literal("treasury").executes(c->player(c,Ui::treasury)));
        d.register(root);d.register(literal("k").redirect(d.getRoot().getChild("kingdom")));
        var admin=literal("kingdomadmin").requires(source->{int level=KingdomsMod.service==null?2:s().config.opLevel;return source.permissions().hasPermission(switch(level){case 1->Permissions.COMMANDS_MODERATOR;case 3->Permissions.COMMANDS_ADMIN;case 4->Permissions.COMMANDS_OWNER;default->Permissions.COMMANDS_GAMEMASTER;});});
        admin.then(literal("bluemap").then(literal("set").then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(AdminSettings.keys(BlueMapConfig.class),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->AdminSettings.set(next.blueMap,str(c,"key"),str(c,"value")))))))));
        admin.then(literal("reload").executes(c->admin(c,()->{Config next=KingdomsMod.configStore.read("config.json",Config.class,new Config());next.validate();s().airDrops.validateConfiguration(next.airDrops);s().artifacts.validateConfiguration(next.artifacts);KingdomsMod.configStore.write("config.json",next);s().config=next;})));
        admin.then(literal("set").then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Arrays.stream(Config.class.getFields()).filter(f->f.getType().isPrimitive()||f.getType()==String.class).map(Field::getName),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->{Config next=Store.JSON.fromJson(Store.JSON.toJson(s().config),Config.class);try{Field f=Config.class.getField(str(c,"key"));Class<?> t=f.getType();String value=str(c,"value");if(t==long.class)f.setLong(next,MONEY_SETTINGS.contains(f.getName())?MoneyInput.parse(value):Long.parseLong(value));else if(t==int.class)f.setInt(next,Integer.parseInt(value));else if(t==boolean.class){if(!value.equals("true")&&!value.equals("false"))throw new IllegalArgumentException("Use true or false.");f.setBoolean(next,Boolean.parseBoolean(value));}else if(t==String.class)f.set(next,value);else throw new IllegalArgumentException("Edit this collection in config.json and reload.");}catch(ReflectiveOperationException e){throw new IllegalArgumentException("Unknown setting.");}next.validate();s().airDrops.validateConfiguration(next.airDrops);s().artifacts.validateConfiguration(next.artifacts);KingdomsMod.configStore.write("config.json",next);s().config=next;})))));
        admin.then(literal("beaconprice").then(argument("effect",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(Arrays.stream(BeaconPower.values()).map(BeaconPower::key),b)).then(argument("amount",StringArgumentType.greedyString()).executes(c->admin(c,()->{BeaconPower power=option(BeaconPower.class,str(c,"effect"));long amount=MoneyInput.parse(str(c,"amount"));Config next=Store.JSON.fromJson(Store.JSON.toJson(s().config),Config.class);next.beaconEffectFees.put(power.key(),amount);next.validate();s().airDrops.validateConfiguration(next.airDrops);s().artifacts.validateConfiguration(next.artifacts);KingdomsMod.configStore.write("config.json",next);s().config=next;})))));
        admin.then(literal("cap").then(argument("kingdom",StringArgumentType.string()).then(argument("kind",StringArgumentType.word()).then(argument("amount",IntegerArgumentType.integer(0,100000)).executes(c->admin(c,()->{Kingdom k=s().named(str(c,"kingdom"));int amount=IntegerArgumentType.getInteger(c,"amount");String kind=str(c,"kind");if(!kind.equals("members")&&!kind.equals("claims"))throw new IllegalArgumentException("Use members or claims. 0 restores the global cap.");s().edit(k.id,n->{if(kind.equals("members"))n.memberCap=amount;else n.claimCap=amount;});}))))));
        admin.then(literal("endwar").then(argument("kingdom",StringArgumentType.greedyString()).executes(c->admin(c,()->{Kingdom k=s().named(str(c,"kingdom"));War w=Rules.conflict(s().state,k.id,s().now());s().require(w!=null,"No active war.");s().diplomacy.endWar(k.id);}))));
        admin.then(literal("clearcooldown").then(argument("kingdom",StringArgumentType.greedyString()).suggests((c,b)->SharedSuggestionProvider.suggest(s().state.kingdoms.values().stream().map(k->k.name),b)).executes(c->admin(c,()->{Kingdom k=s().named(str(c,"kingdom"));s().clearWarCooldown(k.id);s().audit(c.getSource().getEntity()==null?null:c.getSource().getEntity().getUUID(),"cleared war cooldown and protection for "+k.name);},"War cooldown and protection cleared for "+str(c,"kingdom")+"."))));
        var drops=literal("airdrop");
        drops.then(literal("set").then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(AdminSettings.keys(AirDropConfig.class),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->AdminSettings.set(next.airDrops,str(c,"key"),str(c,"value"))),"AirDrop setting saved. Existing drops keep their saved capture rules and loot.")))));
        drops.then(literal("money").then(argument("day",IntegerArgumentType.integer(1,36500)).then(argument("amount",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->next.airDrops.moneyByDay.put(IntegerArgumentType.getInteger(c,"day"),MoneyInput.parse(str(c,"amount")))),"AirDrop cash reward saved for this day onward. Existing loot is unchanged.")))));
        drops.then(literal("threshold").then(argument("players",IntegerArgumentType.integer(1,10000)).then(argument("drops",IntegerArgumentType.integer(1,20)).executes(c->admin(c,()->AdminSettings.update(s(),next->next.airDrops.playerThresholds.put(IntegerArgumentType.getInteger(c,"players"),IntegerArgumentType.getInteger(c,"drops"))),"AirDrop player threshold saved.")))));
        var spawn=literal("spawn").executes(c->admin(c,()->{ServerPlayer p=adminPlayer(c);s().airDrops.spawnTest(p.level(),p.blockPosition().getX(),p.blockPosition().getZ(),"random",false);},"Test AirDrop spawned at your location."));
        spawn.then(argument("variant",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(java.util.stream.Stream.concat(java.util.stream.Stream.of("random"),s().config.airDrops.variants.stream().map(v->v.key)),b)).executes(c->admin(c,()->{ServerPlayer p=adminPlayer(c);s().airDrops.spawnTest(p.level(),p.blockPosition().getX(),p.blockPosition().getZ(),str(c,"variant"),false);},"Test AirDrop spawned at your location.")).then(literal("landed").executes(c->admin(c,()->{ServerPlayer p=adminPlayer(c);s().airDrops.spawnTest(p.level(),p.blockPosition().getX(),p.blockPosition().getZ(),str(c,"variant"),true);},"Test AirDrop spawned ready to capture."))));
        drops.then(spawn);
        var atVariant=argument("variant",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(java.util.stream.Stream.concat(java.util.stream.Stream.of("random"),s().config.airDrops.variants.stream().map(v->v.key)),b)).executes(c->admin(c,()->s().airDrops.spawnTest(s().airDrops.level(s().config.airDrops.dimension),IntegerArgumentType.getInteger(c,"x"),IntegerArgumentType.getInteger(c,"z"),str(c,"variant"),false),"Test AirDrop spawned at the selected coordinates."));
        atVariant.then(literal("landed").executes(c->admin(c,()->s().airDrops.spawnTest(s().airDrops.level(s().config.airDrops.dimension),IntegerArgumentType.getInteger(c,"x"),IntegerArgumentType.getInteger(c,"z"),str(c,"variant"),true),"Test AirDrop spawned ready to capture.")));
        drops.then(literal("spawnat").then(argument("x",IntegerArgumentType.integer(-29999999,29999999)).then(argument("z",IntegerArgumentType.integer(-29999999,29999999)).then(atVariant))));
        drops.then(literal("land").executes(c->admin(c,()->s().airDrops.landNow(),"Descending AirDrops landed immediately.")));
        drops.then(literal("start").executes(c->admin(c,()->s().airDrops.requestStart(true),"Searching for safe AirDrop sites. Coordinates will be announced when ready.")));
        drops.then(literal("cancel").executes(c->admin(c,()->s().airDrops.cancel(),"Active AirDrops cancelled; earned rewards are preserved.")));
        drops.then(literal("recover").executes(c->admin(c,()->s().airDrops.recoverStorage(),"AirDrop storage and pending deliveries recovered.")));
        drops.then(literal("age").then(argument("day",IntegerArgumentType.integer(1,36500)).executes(c->admin(c,()->s().airDrops.setDay(IntegerArgumentType.getInteger(c,"day")),"AirDrop real-world loot age updated. Existing loot is unchanged."))));
        drops.then(literal("status").executes(c->admin(c,()->c.getSource().sendSuccess(()->AirDrops.text("Loot day "+s().airDrops.day()+" • active drops "+s().airDrops.data.drops.stream().filter(AirDropRules.Drop::active).count()+" • next check "+Ui.clock(s().airDrops.data.nextEvent-s().now())),false))));
        admin.then(drops);
        var artifacts=literal("artifact");
        artifacts.then(literal("set").then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(AdminSettings.keys(ArtifactConfig.class),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->AdminSettings.set(next.artifacts,str(c,"key"),str(c,"value"))),"Artifact setting saved.")))));
        artifacts.then(literal("chance").then(argument("day",IntegerArgumentType.integer(1,36500)).then(argument("chance",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->next.artifacts.chanceByDay.put(IntegerArgumentType.getInteger(c,"day"),AdminSettings.chance(str(c,"chance")))),"Artifact drop chance saved for this day onward.")))));
        var artifactType=argument("type",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(ArtifactConfig.KEYS,b));
        artifactType.then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(AdminSettings.keys(ArtifactConfig.Type.class),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->{var type=next.artifacts.types.get(str(c,"type"));s().require(type!=null,"Unknown artifact type.");AdminSettings.set(type,str(c,"key"),str(c,"value"));}),"Artifact type setting saved. Generated artifacts keep their saved stats."))));
        artifacts.then(literal("type").then(artifactType));
        artifacts.then(literal("variant").then(argument("type",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(ArtifactConfig.KEYS,b)).then(argument("index",IntegerArgumentType.integer(1)).then(argument("key",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(AdminSettings.keys(ArtifactConfig.Variant.class),b)).then(argument("value",StringArgumentType.greedyString()).executes(c->admin(c,()->AdminSettings.update(s(),next->{var type=next.artifacts.types.get(str(c,"type"));int index=IntegerArgumentType.getInteger(c,"index")-1;s().require(type!=null&&index<type.variants.size(),"Unknown artifact type or variant. Variant numbering starts at 1.");AdminSettings.set(type.variants.get(index),str(c,"key"),str(c,"value"));}),"Artifact variant saved. Generated artifacts keep their saved stats.")))))));
        artifacts.then(literal("give").then(argument("type",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(ArtifactConfig.KEYS,b)).executes(c->admin(c,()->s().artifacts.give(adminPlayer(c),str(c,"type")),"Artifact issued."))));
        artifacts.then(literal("retire").then(argument("id",StringArgumentType.word()).executes(c->admin(c,()->s().artifacts.retire(UUID.fromString(str(c,"id"))),"Artifact retired; any surviving copy is invalid."))));
        artifacts.then(literal("status").executes(c->admin(c,()->c.getSource().sendSuccess(()->AirDrops.text("Active artifacts: "+s().artifacts.count()+" • unlimited"),false))));
        artifacts.then(literal("fixer").executes(c->admin(c,()->s().artifacts.giveFixer(adminPlayer(c)),"Artifact Fixer issued.")));
        artifacts.then(literal("inspect").executes(c->admin(c,()->c.getSource().sendSuccess(()->AirDrops.text(s().artifacts.inspect(adminPlayer(c))),false))));
        artifacts.then(literal("recover").executes(c->admin(c,()->s().artifacts.recoverStorage(),"Artifact storage recovered.")));
        admin.then(artifacts);
        admin.then(WarAdmin.node());
        d.register(admin);
    }
    private static ServerPlayer adminPlayer(CommandContext<CommandSourceStack> c){try{return c.getSource().getPlayerOrException();}catch(com.mojang.brigadier.exceptions.CommandSyntaxException e){throw new IllegalArgumentException("Use spawnat from the console, or run spawn as a player.");}}
    private static int admin(CommandContext<CommandSourceStack> c,Runnable action){return admin(c,action,"Kingdoms updated.");}
    private static int admin(CommandContext<CommandSourceStack> c,Runnable action,String success){try{action.run();c.getSource().sendSuccess(()->net.minecraft.network.chat.Component.literal(Ui.caps(success)),true);return 1;}catch(Exception e){c.getSource().sendFailure(net.minecraft.network.chat.Component.literal(Ui.caps(e.getMessage())));return 0;}}
}
